import unittest
from candidate import sort_numbers

class TestSortNumbers(unittest.TestCase):
    def test_normal_case_unsorted_words(self):
        self.assertEqual(sort_numbers('three one five'), 'one three five')

    def test_already_sorted_input(self):
        self.assertEqual(sort_numbers('zero one two three four five six seven eight nine'), 
                           'zero one two three four five six seven eight nine')

    def test_reverse_sorted_input(self):
        self.assertEqual(sort_numbers('nine eight seven six five four three two one zero'), 
                           'zero one two three four five six seven eight nine')

    def test_single_number_input(self):
        self.assertEqual(sort_numbers('five'), 'five')

    def test_duplicate_numbers_preserved(self):
        self.assertEqual(sort_numbers('one two one three'), 'one one two three')

    def test_all_identical_numbers(self):
        self.assertEqual(sort_numbers('seven seven seven'), 'seven seven seven')

    def test_empty_string_input(self):
        self.assertEqual(sort_numbers(''), '')

    def test_single_space_input(self):
        self.assertEqual(sort_numbers(' '), '')

    def test_multiple_spaces_between_valid_words(self):
        self.assertEqual(sort_numbers('two   four     nine'), 'two four nine')

    def test_boundary_values_zero_and_nine(self):
        self.assertEqual(sort_numbers('nine zero one eight'), 'zero one eight nine')

    def test_invalid_word_raises_key_error(self):
        with self.assertRaises(KeyError):
            sort_numbers('ten one')

    def test_non_string_input_raises_attribute_error(self):
        with self.assertRaises(AttributeError):
            sort_numbers(123)

    def test_list_input_raises_attribute_error(self):
        with self.assertRaises(AttributeError):
            sort_numbers(['one', 'two'])

    def test_uppercase_word_raises_key_error(self):
        with self.assertRaises(KeyError):
            sort_numbers('One two')

if __name__ == '__main__':
    unittest.main()
